package main

import (
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

var officialMediumFizProfiles = []string{
	"fiz-harness-claude-sonnet-4-6",
	"fiz-harness-codex-gpt-5-4-mini",
	"fiz-harness-pi-gpt-5-4-mini",
	"fiz-harness-opencode-gpt-5-4-mini",
	"fiz-openrouter-claude-sonnet-4-6",
	"fiz-openrouter-gpt-5-4-mini",
}

func officialMediumFizProfilesCSV() string {
	return strings.Join(officialMediumFizProfiles, ",")
}

func TestMediumTerminalbenchComparisonProfilesAreOfficialFizLanes(t *testing.T) {
	repoRoot := benchRepoRoot(t)
	outDir := t.TempDir()

	code := cmdMatrix([]string{
		"--work-dir", repoRoot,
		"--harnesses", "noop",
		"--profiles", officialMediumFizProfilesCSV(),
		"--reps", "1",
		"--out", outDir,
	})
	if code != 0 {
		t.Fatalf("cmdMatrix exit = %d, want 0", code)
	}

	matrix := readMatrixOutput(t, filepath.Join(outDir, "matrix.json"))
	if !reflect.DeepEqual(matrix.Profiles, officialMediumFizProfiles) {
		t.Fatalf("matrix profiles = %v, want %v", matrix.Profiles, officialMediumFizProfiles)
	}
}

func TestRunMediumModelComparisonScriptUsesOnlyFizHarborAgent(t *testing.T) {
	repoRoot := benchRepoRoot(t)

	t.Run("default_force_build", func(t *testing.T) {
		lines := runMediumComparisonScript(t, repoRoot, map[string]string{})
		matrixLine := findLineContaining(t, lines, "matrix --profiles=")
		normalized := strings.ReplaceAll(matrixLine, `\,`, ",")
		if !strings.Contains(matrixLine, "--harnesses=fiz") {
			t.Fatalf("matrix invocation does not pin Harbor to fiz: %s", matrixLine)
		}
		if !strings.Contains(normalized, officialMediumFizProfilesCSV()) {
			t.Fatalf("matrix invocation missing official profile CSV: %s", matrixLine)
		}
		buildLine := findLineContaining(t, lines, " build ")
		if !strings.Contains(buildLine, "HARBOR_FORCE_BUILD=1") {
			t.Fatalf("default run should set HARBOR_FORCE_BUILD=1: %s", buildLine)
		}
	})

	t.Run("force_build_override", func(t *testing.T) {
		lines := runMediumComparisonScript(t, repoRoot, map[string]string{
			"HARBOR_FORCE_BUILD": "0",
		})
		buildLine := findLineContaining(t, lines, " build ")
		if !strings.Contains(buildLine, "HARBOR_FORCE_BUILD=0") {
			t.Fatalf("override run should preserve HARBOR_FORCE_BUILD=0: %s", buildLine)
		}
		matrixLine := findLineContaining(t, lines, "matrix --profiles=")
		normalized := strings.ReplaceAll(matrixLine, `\,`, ",")
		if !strings.Contains(matrixLine, "--harnesses=fiz") {
			t.Fatalf("matrix invocation does not pin Harbor to fiz: %s", matrixLine)
		}
		if !strings.Contains(normalized, officialMediumFizProfilesCSV()) {
			t.Fatalf("matrix invocation missing official profile CSV: %s", matrixLine)
		}
	})
}

func findLineContaining(t *testing.T, lines []string, needle string) string {
	t.Helper()
	for _, line := range lines {
		if strings.Contains(line, needle) {
			return line
		}
	}
	t.Fatalf("did not find line containing %q in %v", needle, lines)
	return ""
}

func runMediumComparisonScript(t *testing.T, repoRoot string, extraEnv map[string]string) []string {
	t.Helper()

	binDir := t.TempDir()
	goLog := filepath.Join(binDir, "go.log")
	goPath := filepath.Join(binDir, "go")
	harborPath := filepath.Join(binDir, "harbor")
	goWrapper := `#!/usr/bin/env bash
set -euo pipefail
{
  printf 'HARBOR_FORCE_BUILD=%s ' "${HARBOR_FORCE_BUILD:-}"
  printf '%q ' go "$@"
  printf '\n'
} >> "$GO_LOG"
case "${1:-}" in
  build)
    out=""
    while (($#)); do
      case "$1" in
        -o)
          out="$2"
          shift 2
          ;;
        *)
          shift
          ;;
      esac
    done
    if [[ -n "$out" ]]; then
      mkdir -p "$(dirname "$out")"
      printf '#!/usr/bin/env bash\nexit 0\n' > "$out"
      chmod 755 "$out"
    fi
    ;;
  run)
    ;;
esac
exit 0
`
	if err := os.WriteFile(goPath, []byte(goWrapper), 0o755); err != nil {
		t.Fatalf("write fake go: %v", err)
	}

	harborWrapper := `#!/usr/bin/env bash
set -euo pipefail
exit 0
`
	if err := os.WriteFile(harborPath, []byte(harborWrapper), 0o755); err != nil {
		t.Fatalf("write fake harbor: %v", err)
	}

	cmd := exec.Command("bash", filepath.Join(repoRoot, "scripts", "benchmark", "run_medium_model_terminalbench_comparison.sh"), "canary")
	cmd.Dir = repoRoot
	cmd.Env = make([]string, 0, len(os.Environ())+5)
	for _, kv := range os.Environ() {
		switch {
		case strings.HasPrefix(kv, "PATH="):
			continue
		case strings.HasPrefix(kv, "OPENROUTER_API_KEY="):
			continue
		case strings.HasPrefix(kv, "GOFLAGS="):
			continue
		case strings.HasPrefix(kv, "GO_LOG="):
			continue
		}
		cmd.Env = append(cmd.Env, kv)
	}
	cmd.Env = append(cmd.Env,
		"PATH="+binDir+string(os.PathListSeparator)+os.Getenv("PATH"),
		"OPENROUTER_API_KEY=dummy",
		"GOFLAGS=-buildvcs=false",
		"GO_LOG="+goLog,
	)
	for k, v := range extraEnv {
		cmd.Env = append(cmd.Env, k+"="+v)
	}
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("medium comparison script failed: %v\n%s", err, string(out))
	}

	raw, err := os.ReadFile(goLog)
	if err != nil {
		t.Fatalf("read go log: %v", err)
	}
	lines := strings.Split(strings.TrimSpace(string(raw)), "\n")
	if len(lines) == 1 && lines[0] == "" {
		return nil
	}
	return lines
}

package profile

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

func writeFile(path string, data []byte) error {
	return os.WriteFile(path, data, 0o644)
}

// repoProfilesDir returns the path to scripts/benchmark/profiles/ relative
// to this test file (internal/benchmark/profile/). Three levels up.
func repoProfilesDir(t *testing.T) string {
	t.Helper()
	return filepath.Join("..", "..", "..", "scripts", "benchmark", "profiles")
}

func TestLoadDir_AllShippedProfilesValidate(t *testing.T) {
	profiles, err := LoadDir(repoProfilesDir(t))
	require.NoError(t, err)
	require.NotEmpty(t, profiles, "expected at least one shipped profile")

	ids := map[string]*Profile{}
	for _, p := range profiles {
		require.NoError(t, p.Validate(), "profile %s failed validation", p.ID)
		ids[p.ID] = p
	}

	// SD-010 §3 + bead AC: smoke + noop fixtures must ship in v1.
	require.Contains(t, ids, "smoke")
	require.Contains(t, ids, "noop")
	// Phase A.1 anchor: gpt-5-mini via OpenRouter.
	require.Contains(t, ids, "gpt-5-mini")
	// TerminalBench medium comparison lanes.
	require.Contains(t, ids, "fiz-harness-claude-sonnet-4-6")
	require.Contains(t, ids, "fiz-harness-codex-gpt-5-4-mini")
	require.Contains(t, ids, "fiz-harness-pi-gpt-5-4-mini")
	require.Contains(t, ids, "fiz-harness-opencode-gpt-5-4-mini")
	require.Contains(t, ids, "fiz-openrouter-claude-sonnet-4-6")
	require.Contains(t, ids, "fiz-openrouter-gpt-5-4-mini")
}

func TestLoad_GPT5MiniAnchorProfile(t *testing.T) {
	p, err := Load(filepath.Join(repoProfilesDir(t), "gpt-5-mini.yaml"))
	require.NoError(t, err)
	require.Equal(t, "gpt-5-mini", p.ID)
	require.Equal(t, ProviderOpenAICompat, p.Provider.Type)
	require.Equal(t, "openai/gpt-5-mini", p.Provider.Model)
	require.Equal(t, "OPENROUTER_API_KEY", p.Provider.APIKeyEnv)
	// Census §5 pricing snapshot — values must stay inside the ≤ $3/Mtok
	// output bracket that selected this row.
	require.Equal(t, 2.00, p.Pricing.OutputUSDPerMTok)
	require.Equal(t, 0.25, p.Pricing.InputUSDPerMTok)
	require.Equal(t, 0.05, p.Pricing.CachedInputUSDPerMTok)
	require.LessOrEqual(t, p.Pricing.OutputUSDPerMTok, 3.00)
	require.Equal(t, 16384, p.Limits.MaxOutputTokens)
	require.Greater(t, p.Limits.ContextTokens, 0)
	require.Greater(t, p.Limits.RateLimitRPM, 0)
	require.Greater(t, p.Limits.RateLimitTPM, 0)
	require.Equal(t, "medium", p.Sampling.Reasoning)
	require.Equal(t, "2026-04-30", p.Versioning.ResolvedAt)
	require.NotEmpty(t, p.Versioning.Snapshot)
}

func TestLoad_SmokeProfileFields(t *testing.T) {
	p, err := Load(filepath.Join(repoProfilesDir(t), "smoke.yaml"))
	require.NoError(t, err)
	require.Equal(t, "smoke", p.ID)
	require.Equal(t, ProviderOpenAICompat, p.Provider.Type)
	require.Equal(t, "OPENAI_API_KEY", p.Provider.APIKeyEnv)
	require.Greater(t, p.Limits.MaxOutputTokens, 0)
	require.Greater(t, p.Limits.ContextTokens, 0)
	require.NotEmpty(t, p.Versioning.ResolvedAt)
	require.NotEmpty(t, p.Path)
}

func TestLoad_NoopProfileFields(t *testing.T) {
	p, err := Load(filepath.Join(repoProfilesDir(t), "noop.yaml"))
	require.NoError(t, err)
	require.Equal(t, "noop", p.ID)
	require.Equal(t, ProviderOpenAICompat, p.Provider.Type)
	require.Equal(t, 0.0, p.Pricing.InputUSDPerMTok)
	require.Equal(t, "noop-fixture", p.Versioning.Snapshot)
}

func TestValidate_RejectsMissingFields(t *testing.T) {
	cases := []struct {
		name    string
		mutate  func(p *Profile)
		wantSub string
	}{
		{"missing id", func(p *Profile) { p.ID = "" }, "id is required"},
		{"bad provider type", func(p *Profile) { p.Provider.Type = "bedrock" }, "provider.type"},
		{"missing model", func(p *Profile) { p.Provider.Model = "" }, "provider.model"},
		{"missing base_url", func(p *Profile) { p.Provider.BaseURL = "" }, "provider.base_url"},
		{"missing api_key_env", func(p *Profile) { p.Provider.APIKeyEnv = "" }, "provider.api_key_env"},
		{"negative pricing", func(p *Profile) { p.Pricing.InputUSDPerMTok = -1 }, "pricing"},
		{"zero max_output", func(p *Profile) { p.Limits.MaxOutputTokens = 0 }, "max_output_tokens"},
		{"zero context", func(p *Profile) { p.Limits.ContextTokens = 0 }, "context_tokens"},
		{"missing resolved_at", func(p *Profile) { p.Versioning.ResolvedAt = "" }, "resolved_at"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			p := goodProfile()
			tc.mutate(&p)
			err := p.Validate()
			require.Error(t, err)
			require.Contains(t, err.Error(), tc.wantSub)
		})
	}
}

func TestLoad_RejectsUnknownFields(t *testing.T) {
	dir := t.TempDir()
	bad := filepath.Join(dir, "bad.yaml")
	require.NoError(t, writeFile(bad, []byte(`
id: bad
provider: {type: openai, model: m, base_url: https://x, api_key_env: K}
pricing: {input_usd_per_mtok: 1, output_usd_per_mtok: 1, cached_input_usd_per_mtok: 0}
limits: {max_output_tokens: 1, context_tokens: 1, rate_limit_rpm: 1, rate_limit_tpm: 1}
sampling: {temperature: 0}
versioning: {resolved_at: "2026-04-29", snapshot: ""}
unknown_top_level: oops
`)))
	_, err := Load(bad)
	require.Error(t, err)
}

func goodProfile() Profile {
	return Profile{
		ID: "x",
		Provider: Provider{
			Type:      ProviderOpenAI,
			Model:     "m",
			BaseURL:   "https://api.example.com",
			APIKeyEnv: "K",
		},
		Pricing:    Pricing{InputUSDPerMTok: 1, OutputUSDPerMTok: 1},
		Limits:     Limits{MaxOutputTokens: 1024, ContextTokens: 8192},
		Sampling:   Sampling{Temperature: 0},
		Versioning: Versioning{ResolvedAt: "2026-04-29"},
	}
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/DocumentDrivenDX/fizeau/internal/benchmark/profile"
)

const defaultProfilesDir = "scripts/benchmark/profiles"

func cmdProfiles(args []string) int {
	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "Usage: %s profiles <subcommand>\n\nSubcommands:\n  list   List profiles under scripts/benchmark/profiles/\n", benchCommandName())
		return 2
	}
	switch args[0] {
	case "list":
		return cmdProfilesList(args[1:])
	case "help", "-h", "--help":
		fmt.Fprintf(os.Stderr, "Usage: %s profiles list [--dir <path>] [--json]\n", benchCommandName())
		return 0
	default:
		fmt.Fprintf(os.Stderr, "%s profiles: unknown subcommand %q\n", benchCommandName(), args[0])
		return 2
	}
}

func cmdProfilesList(args []string) int {
	fs := flagSet("profiles list")
	dir := fs.String("dir", "", "Profiles directory (default: scripts/benchmark/profiles relative to --work-dir)")
	workDir := fs.String("work-dir", "", "Repository root (default: cwd)")
	jsonOut := fs.Bool("json", false, "Emit JSON array instead of table")
	if err := fs.Parse(args); err != nil {
		return 2
	}

	profilesDir := *dir
	if profilesDir == "" {
		profilesDir = filepath.Join(resolveWorkDir(*workDir), defaultProfilesDir)
	}

	profiles, err := profile.LoadDir(profilesDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s profiles list: %v\n", benchCommandName(), err)
		return 1
	}

	if *jsonOut {
		data, _ := json.MarshalIndent(profiles, "", "  ")
		fmt.Println(string(data))
		return 0
	}

	if len(profiles) == 0 {
		fmt.Printf("No profiles found in %s.\n", profilesDir)
		return 0
	}

	fmt.Printf("%-24s %-14s %-32s %-12s %-12s\n", "ID", "PROVIDER", "MODEL", "IN $/Mtok", "OUT $/Mtok")
	fmt.Printf("%-24s %-14s %-32s %-12s %-12s\n", "--", "--------", "-----", "---------", "----------")
	for _, p := range profiles {
		fmt.Printf("%-24s %-14s %-32s %-12.4f %-12.4f\n",
			p.ID,
			string(p.Provider.Type),
			p.Provider.Model,
			p.Pricing.InputUSDPerMTok,
			p.Pricing.OutputUSDPerMTok,
		)
	}
	return 0
}
